BEGIN;
CREATE TABLE IF NOT EXISTS users(id SERIAL PRIMARY KEY,email VARCHAR(255) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,name VARCHAR(255) NOT NULL,role VARCHAR(50) NOT NULL DEFAULT 'user',created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS cobot_workspaces(id UUID PRIMARY KEY,name TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS cobot_workspace_members(workspace_id UUID REFERENCES cobot_workspaces(id),user_id INTEGER NOT NULL,role TEXT NOT NULL CHECK(role IN('owner','integrator','engineer','safety_reviewer','operator','viewer')),active BOOLEAN DEFAULT true,PRIMARY KEY(workspace_id,user_id));
CREATE TABLE IF NOT EXISTS cobot_idempotency(actor_id INTEGER,key TEXT,response JSONB NOT NULL,PRIMARY KEY(actor_id,key));
CREATE TABLE IF NOT EXISTS cobot_devices(id BIGSERIAL PRIMARY KEY,workspace_id UUID NOT NULL REFERENCES cobot_workspaces(id),device_identifier TEXT NOT NULL UNIQUE,public_key TEXT NOT NULL,device_type TEXT NOT NULL,last_sequence BIGINT NOT NULL DEFAULT 0,last_seen_at TIMESTAMPTZ,active BOOLEAN NOT NULL,created_by INTEGER NOT NULL,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS cobot_telemetry_batches(id BIGSERIAL PRIMARY KEY,workspace_id UUID NOT NULL REFERENCES cobot_workspaces(id),device_id BIGINT NOT NULL REFERENCES cobot_devices(id),sequence BIGINT NOT NULL,captured_at TIMESTAMPTZ NOT NULL,payload JSONB NOT NULL,checksum TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('accepted','quarantined','processed')),created_at TIMESTAMPTZ DEFAULT now(),UNIQUE(device_id,sequence));
CREATE TABLE IF NOT EXISTS cobot_logic_versions(id BIGSERIAL PRIMARY KEY,workspace_id UUID NOT NULL REFERENCES cobot_workspaces(id),name TEXT NOT NULL,version TEXT NOT NULL,artifact_uri TEXT NOT NULL,checksum TEXT NOT NULL,thresholds JSONB NOT NULL,state TEXT NOT NULL CHECK(state IN('pending_safety_review','approved','rejected','retired')),created_by INTEGER NOT NULL,reviewed_by INTEGER,review_reason TEXT,reviewed_at TIMESTAMPTZ,created_at TIMESTAMPTZ DEFAULT now(),UNIQUE(workspace_id,name,version));
CREATE TABLE IF NOT EXISTS cobot_detections(id BIGSERIAL PRIMARY KEY,workspace_id UUID NOT NULL REFERENCES cobot_workspaces(id),telemetry_batch_id BIGINT REFERENCES cobot_telemetry_batches(id),logic_version_id BIGINT REFERENCES cobot_logic_versions(id),kind TEXT NOT NULL,severity TEXT NOT NULL CHECK(severity IN('info','warning','hazard')),confidence NUMERIC NOT NULL CHECK(confidence BETWEEN 0 AND 1),evidence JSONB NOT NULL,state TEXT NOT NULL CHECK(state IN('pending_review','acknowledged','dismissed','intervention_requested','approved','cancelled','closed')),idempotency_key TEXT NOT NULL,created_by INTEGER NOT NULL,updated_by INTEGER,update_reason TEXT,updated_at TIMESTAMPTZ,created_at TIMESTAMPTZ DEFAULT now(),UNIQUE(workspace_id,idempotency_key));
CREATE TABLE IF NOT EXISTS cobot_operator_overrides(id BIGSERIAL PRIMARY KEY,workspace_id UUID NOT NULL REFERENCES cobot_workspaces(id),detection_id BIGINT REFERENCES cobot_detections(id),action TEXT NOT NULL,reason TEXT NOT NULL,operator_id INTEGER NOT NULL,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS cobot_governance_audit(id BIGSERIAL PRIMARY KEY,workspace_id UUID REFERENCES cobot_workspaces(id),actor_id INTEGER NOT NULL,action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,details JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ DEFAULT now());
CREATE INDEX IF NOT EXISTS cobot_detection_review_idx ON cobot_detections(workspace_id,state);
COMMIT;
